import{_ as s,a0 as u,w as r,s as p,ao as l,I as i,x as n,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知 | LCTT x X-CMD","titleTemplate":false,"description":"快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知 | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知 | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/How To Enable Desktop Notification For VLC In Ubuntu 13.10 [Quick Tip]","title":"快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知","tag":"201403","desc":""},"relativePath":"201403/How To Enable Desktop Notification For VLC In Ubuntu 13.10 [Quick Tip].md","filePath":"[post].md"}'),b={name:"201403/How To Enable Desktop Notification For VLC In Ubuntu 13.10 [Quick Tip].md"};function f(d,t,C,m,g,c){const o=u("Link");return r(),p("div",null,[t[11]||(t[11]=l('<h1 id="快速技巧-如何在-ubuntu-13-10-下啓用-vlc-桌面通知" tabindex="-1">快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知 <a class="header-anchor" href="#快速技巧-如何在-ubuntu-13-10-下啓用-vlc-桌面通知" aria-label="Permalink to “快速技巧：如何在 Ubuntu 13.10 下啓用 VLC 桌面通知”">​</a></h1><p>我必須説 VLC 是目前最好的視頻文件播放器。VLC 播放器有許多隱藏特性你可能還不知道。其中一個就是桌面通知。在本教程中,我們將會看到<strong>如何在 Ubuntu 13.10 和其它版本下啓用 VLC 桌面通知</strong>。</p><h3 id="在-ubuntu-下啓用-vlc-桌面通知" tabindex="-1">在 Ubuntu 下啓用 VLC 桌面通知: <a class="header-anchor" href="#在-ubuntu-下啓用-vlc-桌面通知" aria-label="Permalink to “在 Ubuntu 下啓用 VLC 桌面通知:”">​</a></h3><p>要想在 Ubuntu 下啓用桌面通知,依照下面步驟進行:</p><h4 id="步驟-1" tabindex="-1">步驟 1: <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1:”">​</a></h4><p>打開 VLC 播放器。在頂部菜單內,進入 <strong>Tools</strong>，接着進入 <strong>Preferences</strong>。</p><p><strong>VLC-&gt;Tools-&gt;Preferences</strong></p><p><img src="http://itsfoss.com/wp-content/uploads/2014/02/VLC_Notification_Ubuntu.jpeg" alt=""></p><h4 id="步驟-2" tabindex="-1">步驟 2: <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2:”">​</a></h4><p>選擇底部的 <strong>All</strong> 按鈕:</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/02/VLC_Notification_Ubuntu_1.jpeg" alt=""></p><h4 id="步驟-3" tabindex="-1">步驟 3: <a class="header-anchor" href="#步驟-3" aria-label="Permalink to “步驟 3:”">​</a></h4><p>現在從左邊欄中選擇 <strong>Control interfaces</strong>。在這裏,選擇 <strong>LibNotify Notification Plugin</strong> 並保存。這個會在帶 Unity 的 Ubuntu 中啓用桌面通知。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/02/VLC_Notification_Ubuntu_2.jpeg" alt=""></p><p>默認通知會顯示4000ms也就是4秒。你可以通過控制接口下的通知選項來更改。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/02/VLC_Notification_Ubuntu_3.jpeg" alt=""></p><p>就這麼簡單！你可以在播放音頻或者視頻文件的時候看到通知。它與 Ubuntu 環境完美地整合在一起:</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/02/VLC_Notification_Ubuntu_4.jpeg" alt=""></p><p>我希望這個啓用桌面通知的快速技巧能使你的 VLC 更加 Ubuntu化，更加時尚化。你覺得如何?</p><hr>',20)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://itsfoss.com/enable-desktop-notification-vlc-ubuntu/"},{default:a(()=>[...t[0]||(t[0]=[n("http://itsfoss.com/enable-desktop-notification-vlc-ubuntu/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=n("譯者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:a(()=>[...t[2]||(t[2]=[n("geekpi",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),e(o,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const V=s(b,[["render",f]]);export{T as __pageData,V as default};
